                  call. = FALSE)
                algos = setdiff(algos, "CBSX")
                if (length(algos) == 0) {
                  return(NULL)
                }
            }
        }
        if (doParallel == T && is.null(workers)) {
            workers = max(1, parallel::detectCores() - 1)
        }
